package com.haolin.vontlocal;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.widget.RemoteViews;

public final class LinkWidget extends AppWidgetProvider {
    static PendingIntent action(Context c,String action){Intent i=new Intent(c,LinkService.class).setAction(LinkService.PREFIX+action).setData(Uri.parse("vontlocal://room/"+action)).putExtra("source","widget");return PendingIntent.getForegroundService(c,action.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);update(c,m,m.getAppWidgetIds(new ComponentName(c,LinkWidget.class)));}
    static void update(Context c,AppWidgetManager m,int[] ids){for(int id:ids){int width=m.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,360);m.updateAppWidget(id,views(c,width>=260,width));}}
    static RemoteViews views(Context c,boolean wide){return views(c,wide,360);}
    static RemoteViews views(Context c,boolean wide,int width){Ui u=new Ui(c);RemoteViews v=new RemoteViews(c.getPackageName(),wide?R.layout.room_widget_wide:R.layout.room_widget);boolean active=FocusStore.running();
        v.setImageViewResource(R.id.widget_background_layer,u.dark?R.drawable.widget_background_dark:R.drawable.widget_background);v.setInt(R.id.widget_background_layer,"setImageAlpha",WidgetAppearance.alpha(WidgetAppearance.transparency(c)));
        PendingIntent open=PendingIntent.getActivity(c,51,new Intent(c,HomeActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_title_area,open);v.setTextColor(R.id.widget_title,u.text);
        v.setOnClickPendingIntent(R.id.widget_work,action(c,"work"));v.setOnClickPendingIntent(R.id.widget_wind_down,action(c,"wind_down"));v.setOnClickPendingIntent(R.id.widget_sleep,action(c,"bed"));v.setOnClickPendingIntent(R.id.widget_off,action(c,"off"));
        v.setOnClickPendingIntent(R.id.widget_focus_action,active?FocusStopReceiver.pending(c):FocusConfirmActivity.pending(c));v.setTextViewText(R.id.widget_focus_action,active?"结束":"开始");v.setContentDescription(R.id.widget_focus_action,active?"结束办公提醒并保留灯光":"打开办公提醒确认，不直接调灯");
        v.setOnClickPendingIntent(R.id.widget_focus_info,PendingIntent.getActivity(c,613,new Intent(c,FocusSettingsActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));v.setTextViewText(R.id.widget_focus_title,FocusStore.title(c));String detail=FocusStore.detail(c);if(wide)detail=detail.replace("工作 ","工作").replace("休息 ","休息").replace(" 分钟","分钟");if(!active&&detail.length()>26)detail="提醒已停止 · 点此查看";v.setTextViewText(R.id.widget_focus_detail,detail);v.setTextColor(R.id.widget_focus_title,u.text);v.setTextColor(R.id.widget_focus_detail,u.muted);
        int chip=wide?(u.dark?R.drawable.widget_chip_airy_dark:R.drawable.widget_chip_airy):(u.dark?R.drawable.widget_chip_dark:R.drawable.widget_chip),selected=wide?(u.dark?R.drawable.widget_selected_airy_dark:R.drawable.widget_selected_airy):(u.dark?R.drawable.widget_selected_dark:R.drawable.widget_selected);v.setInt(R.id.widget_off,"setBackgroundResource",chip);v.setTextColor(R.id.widget_off_label,u.text);v.setInt(R.id.widget_off_icon,"setColorFilter",u.text);v.setInt(R.id.widget_focus_action,"setBackgroundResource",active?chip:selected);v.setTextColor(R.id.widget_focus_action,active?u.text:u.accent);
        int[] ids={R.id.widget_work,R.id.widget_wind_down,R.id.widget_sleep},labels={R.id.widget_work_label,R.id.widget_wind_down_label,R.id.widget_sleep_label},icons={R.id.widget_work_icon,R.id.widget_wind_down_icon,R.id.widget_sleep_icon};String[] names={"work","wind_down","bed"};String last="";if(active){String p=FocusStore.state(c).optString("phase");if(!"preparing".equals(p))last="work";}else{org.json.JSONObject s=LinkStore.status(c);if(s.optBoolean("completed")&&"success".equals(s.optJSONObject("screenbar")==null?"":s.optJSONObject("screenbar").optString("status")))last=LinkPolicy.canonical(s.optString("action"));}
        for(int i=0;i<ids.length;i++){boolean on=names[i].equals(last);v.setInt(ids[i],"setBackgroundResource",on?selected:chip);v.setTextColor(labels[i],on?u.accent:u.text);v.setInt(icons[i],"setColorFilter",on?u.accent:u.text);}
        if(wide){v.setTextColor(R.id.widget_title,u.muted);for(int label:labels)v.setTextViewTextSize(label,android.util.TypedValue.COMPLEX_UNIT_SP,width<320?11:13);v.setTextViewTextSize(R.id.widget_off_label,android.util.TypedValue.COMPLEX_UNIT_SP,width<320?11:13);v.setInt(R.id.widget_focus_icon,"setColorFilter",u.text);v.setInt(R.id.widget_divider,"setBackgroundColor",u.line);}return v;
    }
    @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){update(c,m,ids);}
    @Override public void onEnabled(Context c){updateAll(c);}
    @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle options){update(c,m,new int[]{id});}
}
